function recipient(){const value=String(globalThis.COLAVA?.customRequestEmail||'').trim();return /^[^\s@?&#]+@[^\s@?&#]+\.[^\s@?&#]+$/.test(value)?value:'';}
function markup(lang,mode){const t=COPY[lang],food=mode==='food';return `<section id="custom" class="custom section"><div class="section-label">COLAVA ${mode.toUpperCase()} / ${t.label}</div><div class="process-heading"><h2>${food?t.titleFood:t.titleCandles}</h2><p>${food?t.introFood:t.introCandles}</p></div><div class="custom-steps">${t.steps.map((s,i)=>`<div><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div><p class="custom-use">${food?t.foodUse:t.candleUse}</p><details class="custom-details"><summary>${t.cta}<span aria-hidden="true">+</span></summary><form id="custom-form" data-custom-lang="${lang}" data-custom-mode="${mode}"><h3>${t.formTitle}</h3><p>${t.formIntro}</p><div class="form-grid"><label>${t.name}<input name="name" required maxlength="120" autocomplete="name"></label><label>${t.email}<input name="email" type="email" required maxlength="160" autocomplete="email"></label><label>${food?t.companyFood:t.companyCandles}<input name="company" maxlength="160" autocomplete="organization"></label><label>${t.dimensions}<input name="dimensions" required maxlength="160" placeholder="40 × 40 × 25 mm"></label><label>${t.quantity}<input name="quantity" type="number" min="1" max="100000" required value="1"></label><label>${food?t.materialFood:t.materialCandles}<input name="material" required maxlength="300"></label><label class="full">${t.notes}<textarea name="notes" rows="4" required maxlength="3000"></textarea></label><label class="full">${t.files}<input name="designs" type="file" accept=".png,.jpg,.jpeg,.pdf,.stl,.step,.stp" multiple required aria-describedby="custom-file-help"></label></div><p id="custom-file-help" class="form-note">${t.fileHint}</p><p class="form-note">${t.privacy}</p><p class="custom-status">${recipient()?t.emailReady:t.pending}</p><button class="button blue" type="submit">${recipient()?t.send:t.download}<span>↓</span></button><p class="form-result" role="status" aria-live="polite"></p></form></details></section>`;}
// Store-only ZIP: files are packaged locally and never uploaded by this page.
function crc32(a){let n=-1;for(const v of a){n^=v;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xEDB88320:0);}return (n^-1)>>>0;}
function makeZip(entries){const parts=[],central=[];let offset=0,centralLength=0;const enc=new TextEncoder();for(const entry of entries){const name=enc.encode(entry.name),bytes=entry.bytes,crc=crc32(bytes);let head=new Uint8Array(30+name.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,name.length,true);head.set(name,30);parts.push(head,bytes);let ch=new Uint8Array(46+name.length),d=new DataView(ch.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);ch.set(name,46);central.push(ch);centralLength+=ch.length;offset+=head.length+bytes.length;}const tail=new Uint8Array(22),d=new DataView(tail.buffer);d.setUint32(0,0x06054b50,true);d.setUint16(8,entries.length,true);d.setUint16(10,entries.length,true);d.setUint32(12,centralLength,true);d.setUint32(16,offset,true);return new Blob([...parts,...central,tail],{type:'application/zip'});}
function validFiles(files){return files.length>0&&files.length<=5&&files.every(f=>/\.(png|jpe?g|pdf|stl|step|stp)$/i.test(f.name)&&f.size<=15*1024*1024)&&files.reduce((n,f)=>n+f.size,0)<=30*1024*1024;}
if(typeof document!=='undefined')document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='custom-form')return;e.preventDefault();const t=COPY[form.dataset.customLang],mode=form.dataset.customMode,files=Array.from(form.elements.designs.files),result=form.querySelector('.form-result'),button=form.querySelector('[type=submit]');if(!validFiles(files)){result.textContent=files.length?t.error:t.required;return;}button.disabled=true;try{const values=new FormData(form);const brief=['COLAVA / CUSTOM '+mode.toUpperCase(),'','Name: '+values.get('name'),'Email: '+values.get('email'),'Company: '+values.get('company'),'Dimensions: '+values.get('dimensions'),'Quantity: '+values.get('quantity'),'Material / conditions: '+values.get('material'),'Notes: '+values.get('notes'),'','Files:',...files.map(f=>f.name),'','Status: customer brief only; feasibility, materials, quote and timing not yet confirmed.'].join('\n');const entries=[{name:'COLAVA-brief.txt',bytes:new TextEncoder().encode(brief)}];for(let i=0;i<files.length;i++){entries.push({name:'designs/'+(i+1)+'-'+files[i].name.replace(/[^a-zA-Z0-9._-]/g,'_'),bytes:new Uint8Array(await files[i].arrayBuffer())});}const blob=makeZip(entries),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='COLAVA-Custom-'+mode+'.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);const to=recipient();result.textContent=to?t.doneEmail:t.done;if(to){const body=brief+'\n\n'+t.emailReady;location.href='mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent(t.subject+' / '+mode)+'&body='+encodeURIComponent(body);}}catch{result.textContent=form.dataset.customLang==='it'?'Impossibile preparare il pacchetto. Riprova con file più piccoli.':'Could not prepare the package. Try smaller files.';}finally{button.disabled=false;}});
const api={markup,makeZip,validFiles,recipient};if(typeof module!=='undefined')module.exports=api;else globalThis.COLAVACustom=api;
